{
    "name": "@encoredigitalgroup/opencode",
    "type": "module",
    "version": "0.2.11",
    "description": "OpenCode planning pickers, a todo tracker, and a quota sidebar.",
    "publishConfig": {
        "access": "public"
    },
    "keywords": [
        "opencode",
        "opencode-plugin",
        "planning",
        "skills"
    ],
    "engines": {
        "bun": ">=1.4.0"
    },
    "dependencies": {
        "@opentui/solid": "0.5.14",
        "@opentelemetry/api": "~1.9.1",
        "jsonc-parser": "^3.3.1",
        "solid-js": "1.9.12"
    },
    "devDependencies": {
        "@opencode/cli": "2.1.4",
        "@opencode/client": "2.1.4",
        "@opencode/plugin": "2.1.4",
        "@opentui/core": "0.5.14",
        "@types/node": "^22.20.5",
        "@types/bun": "1.4.0",
        "tsfmt": "^0.3.0-beta9",
        "typescript": "5.8.2"
    },
    "scripts": {
        "build": "rm -rf dist && bun build src/server/index.ts src/tui/index.tsx --outdir dist --target bun --external '@opencode/plugin' --external '@opencode/plugin/*' --external '@opentui/core' --external '@opentui/core/*' --external '@opentui/solid' --external '@opentui/solid/*' && tsc --emitDeclarationOnly",
        "check": "bun run typecheck && bun run build",
        "local:install": "bun run build && bun tools/local-plugin.ts install",
        "local:uninstall": "bun tools/local-plugin.ts uninstall",
        "pack:check": "bun pm pack --dry-run",
        "test": "bun test",
        "typecheck": "tsc --noEmit"
    },
    "types": "./dist/server/index.d.ts",
    "main": "./dist/server/index.js",
    "exports": {
        ".": {
            "types": "./dist/server/index.d.ts",
            "default": "./dist/server/index.js"
        },
        "./server": {
            "types": "./dist/server/index.d.ts",
            "default": "./dist/server/index.js"
        },
        "./tui": {
            "types": "./dist/tui/index.d.ts",
            "default": "./dist/tui/index.js"
        }
    },
    "files": [
        "dist",
        "server.js",
        "tui.js",
        "README.md",
        "LICENSE.md",
        "LICENSES"
    ],
    "license": "proprietary",
    "peerDependencies": {
        "@opencode/plugin": "^2.0.22"
    },
    "oc-plugin": [
        "server",
        "tui"
    ],
    "trustedDependencies": [
        "@opencode/cli"
    ]
}
